function drawPreview(){const n=card(search.preview),container=$('#fp-preview-content');$('#fp-open-result').disabled=!n||search.pending;if(!n){container.innerHTML='<div class="fp-empty"><h3>让想法浮现</h3><p>在左侧输入关键词或选择标签</p></div>';$('#fp-preview-nav').innerHTML='';return}const u=units(search.q);container.innerHTML=`<p class="fp-eyebrow">卡片预览 · 不改变画布</p><h2>${highlight(n.title||'未命名卡片',u)}</h2><div class="fp-preview-tags">${(n.tags||[]).map(tagHTML).join('')}</div><div class="fp-preview-body fp-body">${n.bodyHtml?sanitize(n.bodyHtml):esc(n.body||'').replace(/\n/g,'<br>')}</div>`;const count=richMatches($('.fp-preview-body'),u);search.hit=Math.min(search.hit,Math.max(0,count-1));$$('[data-hit]',container).forEach(e=>e.classList.toggle('current',Number(e.dataset.hit)===search.hit));$('#fp-preview-nav').innerHTML=count?`<button id="fp-hit-prev" class="fp-icon" title="上一个命中" ${search.hit===0?'disabled':''}>↑</button><span>${search.hit+1} / ${count}</span><button id="fp-hit-next" class="fp-icon" title="下一个命中" ${search.hit===count-1?'disabled':''}>↓</button>`:'正文预览';const locate=()=>{const hit=$(`[data-hit="${search.hit}"]`,container);if(hit)container.scrollTop+=hit.getBoundingClientRect().top-container.getBoundingClientRect().top-container.clientHeight*.35};const move=d=>{search.hit+=d;search.scroll=0;drawPreview()};if(count){$('#fp-hit-prev').onclick=()=>move(-1);$('#fp-hit-next').onclick=()=>move(1)}if(search.scroll)container.scrollTop=search.scroll;else if(count)requestAnimationFrame(locate);else container.scrollTop=0;container.onscroll=()=>{search.scroll=container.scrollTop};$$('img',container).forEach(img=>img.ondblclick=()=>viewImage(img));$$('a',container).forEach(a=>a.onclick=e=>{e.preventDefault();if(/^https?:|mailto:/i.test(a.href))window.open(a.href,'_blank','noopener,noreferrer')})}
function openResult(){if(search.pending){runSearch();return}const n=card(search.preview);if(!n){runSearch();return}recordSearch(true);const id=n.id,terms=units(search.q),hit=search.hit,wasOpen=!!editorId;closeSearch();fw().select([id]);fw().centerOn?.(id);followSelection();fw().render();if(wasOpen){if(editorId!==id)openEditor(id);findState={terms,hit};drawEditorFind()}}
function searchPopover(type){if(search.pop===type){search.pop=null;$('#fp-search-pop').innerHTML='';return}search.pop=type;const host=$('#fp-search-pop');if(type==='tags'){host.innerHTML=`<div class="fp-search-pop"><input id="fp-tag-filter" placeholder="查找已有标签" aria-label="查找已有标签"><div id="fp-tag-options">${project().tags.map(t=>`<label data-option-name="${esc(t.name)}"><input type="checkbox" value="${t.id}" ${search.tags.includes(t.id)?'checked':''}>${tagHTML(t.id)}</label>`).join('')||'<p>没有匹配的标签</p>'}</div><button id="fp-pop-done">完成</button></div>`;$('#fp-tag-filter').oninput=e=>$$('[data-option-name]').forEach(l=>l.hidden=!fold(l.dataset.optionName).includes(fold(e.target.value)));$$('#fp-tag-options input').forEach(el=>el.onchange=()=>{search.tags=el.checked?[...search.tags,el.value]:search.tags.filter(id=>id!==el.value);runSearch()});$('#fp-pop-done').onclick=()=>{host.innerHTML='';search.pop=null}}
else if(type==='info'){host.innerHTML=`<div class="fp-search-pop"><strong>同时包含：${units(search.q).map(esc).join('、')}</strong><p>支持双引号连续文字、英文大小写与全半角。</p><p>不区分英文大小写${searchEngines.opencc==='ready'?'和简繁体':''}；引号中的内容按连续文字匹配。</p><p>${searchEngines.jieba==='ready'?'中文分词已就绪':searchEngines.jieba==='failed'?'中文专业分词不可用，暂用浏览器规则，结果可能不同':'中文分词正在加载，当前暂用浏览器规则'}。${searchEngines.opencc==='ready'?'简繁匹配已就绪':searchEngines.opencc==='failed'?'简繁匹配不可用，目前按原字形匹配':'简繁匹配正在加载，目前按原字形匹配'}。</p>${/["“][^"”]*$/.test(search.q)?'<p>可补全右引号</p>':''}</div>`}
else {host.innerHTML=`<div class="fp-search-pop fp-history-pop"><div class="fp-between"><strong>最近搜索</strong><button id="fp-clear-history" class="fp-subtle">清空历史</button></div>${search.history.map((h,i)=>`<div class="fp-history-item"><button data-history="${i}"><strong>${esc(h.q)||'仅标签'}</strong><div>${h.tags.map(tagHTML).join('')}</div></button><button data-delete-history="${i}" aria-label="删除搜索历史">×</button></div>`).join('')||'<p>还没有搜索记录</p>'}<div id="fp-history-undo"></div></div>`;const remove=i=>{const old=clone(search.history);search.historyDeleted=historyKey({q:search.q,tags:search.tags});search.history=i===null?[]:search.history.filter((h,j)=>j!==i);persistSearch();search.pop=null;searchPopover('history');$('#fp-history-undo').innerHTML='<span>历史已移除</span><button id="fp-undo-history">撤销</button>';$('#fp-undo-history').onclick=()=>{search.history=old;search.historyDeleted=null;persistSearch();search.pop=null;searchPopover('history')}};$('#fp-clear-history').onclick=()=>remove(null);$$('[data-delete-history]').forEach(el=>el.onclick=()=>remove(Number(el.dataset.deleteHistory)));$$('[data-history]').forEach(el=>el.onclick=()=>{const h=search.history[Number(el.dataset.history)];search.q=h.q;search.tags=[...h.tags];$('#fp-query').value=h.q;host.innerHTML='';search.pop=null;runSearch()})}}
function openAI(id){flush();const n=card(id);if(!n)return;returnFocus=document.activeElement;const host=$('#modalHost');host.hidden=false;host.innerHTML=`<div class="fp-backdrop"><section class="fp-ai" role="dialog" aria-modal="true" aria-label="AI 整理示例"><header class="fp-between"><span class="fp-overline">${icon('sparkles','✧')} 按需 AI</span><button id="fp-ai-close" class="fp-icon" aria-label="关闭 AI">×</button></header><h2>给想法一个新的角度</h2><p class="fp-ai-note">本地模拟示例 · 未连接模型 · 不联网查证</p><div class="fp-ai-source"><span>当前卡片</span><strong>${esc(n.title||'未命名卡片')}</strong></div><p>先预览候选，只有你明确添加后才会成为新卡片。</p><div class="fp-ai-actions"><button data-ai="summary">整理为要点</button><button data-ai="questions">列出待思考问题</button></div><div id="fp-ai-candidate"></div><footer>不覆盖原文，不自动连线，不代表事实已核实</footer></section></div>`;const close=()=>{host.innerHTML='';host.hidden=true;returnFocus?.focus?.()};$('#fp-ai-close').onclick=close;$('.fp-backdrop').onmousedown=e=>{if(e.target===e.currentTarget)close()};$('.fp-ai').onkeydown=e=>{e.stopPropagation();if(e.key==='Escape')close();if(e.key==='Tab'){const a=$$('button:not([disabled])',$('.fp-ai'));if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}};$$('[data-ai]').forEach(b=>b.onclick=()=>{const text=b.dataset.ai==='summary'?plain(n).split(/[。！？\n]/).filter(s=>s.trim()).slice(0,5).map(s=>'• '+s.trim()).join('\n')||'• 先补充这张卡片的内容，再整理要点。':`• 「${n.title||'这个想法'}」的关键依据是什么？\n• 还有哪些信息需要补充？\n• 哪些不同角度值得继续探索？`;$('#fp-ai-candidate').innerHTML=`<div class="fp-candidate"><span class="fp-eyebrow">本地模拟候选 · 待你审阅</span><h3>${b.dataset.ai==='summary'?'内容要点':'继续思考'}</h3><div>${esc(text).replace(/\n/g,'<br>')}</div><button id="fp-add-candidate" class="fp-primary">＋ 添加为新卡片</button></div>`;$('#fp-add-candidate').onclick=()=>{if(!card(id)){fw().toast('原卡片已删除，请重新选择');return}fw().transact('添加模拟候选卡片',()=>project().nodes.push({id:fw().uid(),type:'card',x:n.x+n.w+48,y:n.y+40,w:n.w,h:n.h,title:b.dataset.ai==='summary'?'内容要点（模拟候选）':'继续思考（模拟候选）',body:text,tags:[],color:n.color,updatedAt:Date.now()}));fw().toast('候选已添加为新卡片，原文保留');close()}});$('#fp-ai-close').focus()}
function render(){refreshTagColors();if(editorId&&editorProject!==project().id){closeEditor();if(search?.open)closeSearch();search=null;return}if(editorId){const body=$('#fp-body'),n=card(editorId);if((!n&&body)||(n&&!body))renderEditor();else if(n&&body&&!before&&!body.contains(document.activeElement)&&document.activeElement!==$('#fp-title')){if(serializeBody(body)!==(n.bodyHtml||'')){blockSelection=[];imageTarget=null;$('#fp-image-tools')?.remove();body.innerHTML=n.bodyHtml?sanitize(n.bodyHtml):(n.body||'').split('\n').map(p=>`<p>${esc(p)||'<br>'}</p>`).join('');ensureBlocks()}$('#fp-title').value=n.title||'';$('#fp-card-tags').innerHTML=(n.tags||[]).map(tagHTML).join('')}followSelection()}}
